function validate([root, low, high]) {
  if (!Array.isArray(root) || root.length < 1 || root[0] === null) return 'The tree has at least 1 node.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < 1 || v > 100000))) return 'Node values are whole numbers from 1 to 10^5.';
  if (root[root.length - 1] === null) return 'Drop the trailing nulls from the level order.';
  if (!Number.isInteger(low) || !Number.isInteger(high) || low < 1 || high > 100000 || low > high) return 'low and high must satisfy 1 <= low <= high <= 10^5.';
  // Each node keeps the open interval its subtree must stay inside.
  const nodes = [{ val: root[0], below: 0, above: 100001 }];
  let index = 1;
  for (let head = 0; index < root.length; head++) {
    if (head >= nodes.length) return 'The level order has values that have no parent node.';
    const node = nodes[head];
    const left = root[index];
    const right = index + 1 < root.length ? root[index + 1] : null;
    if (left !== null) {
      if (left <= node.below || left >= node.val) return 'This must be a binary search tree: smaller values on the left, larger on the right, all distinct.';
      nodes.push({ val: left, below: node.below, above: node.val });
    }
    if (right !== null) {
      if (right <= node.val || right >= node.above) return 'This must be a binary search tree: smaller values on the left, larger on the right, all distinct.';
      nodes.push({ val: right, below: node.val, above: node.above });
    }
    index += 2;
  }
  if (nodes.length > 20000) return 'The tree has at most 2 * 10^4 nodes.';
  return null;
}

