function rangeSumBST(root, low, high) {
  const sum = (node) => {
    if (node === null) {
      return 0;
    }
    if (node.val < low) {
      return sum(node.right);
    }
    if (node.val > high) {
      return sum(node.left);
    }
    return node.val + sum(node.left) + sum(node.right);
  };
  return sum(root);
}

