function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 950 + pick(50) : 1 + pick(12);
  const maxValue = large || rand() < 0.4 ? 100000 : n + pick(30);
  // A partial shuffle of 1..maxValue picks n distinct values.
  const pool = Array.from({ length: maxValue }, (_, i) => i + 1);
  for (let i = 0; i < n; i++) { const j = i + pick(pool.length - i); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const sorted = pool.slice(0, n).sort((a, b) => a - b);
  // The insertion order decides the shape: random, ascending chain, descending chain or balanced.
  const style = pick(4);
  let order;
  if (style === 0) {
    order = sorted.slice();
    for (let i = order.length - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
  } else if (style === 1) order = sorted.slice();
  else if (style === 2) order = sorted.slice().reverse();
  else {
    order = [];
    const ranges = [[0, n - 1]];
    for (let head = 0; head < ranges.length; head++) {
      const [lo, hi] = ranges[head];
      if (lo > hi) continue;
      const mid = (lo + hi) >> 1;
      order.push(sorted[mid]);
      ranges.push([lo, mid - 1], [mid + 1, hi]);
    }
  }
  const top = { val: order[0], left: null, right: null };
  for (let i = 1; i < order.length; i++) {
    let node = top;
    for (;;) {
      const side = order[i] < node.val ? 'left' : 'right';
      if (!node[side]) { node[side] = { val: order[i], left: null, right: null }; break; }
      node = node[side];
    }
  }
  const root = [];
  const queue = [top];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    if (!node) { root.push(null); continue; }
    root.push(node.val);
    queue.push(node.left, node.right);
  }
  while (root[root.length - 1] === null) root.pop();
  // The range: two tree values, two random values, the whole value range, or a single tree value.
  const mode = pick(4);
  let a, b;
  if (mode === 0) { a = sorted[pick(n)]; b = sorted[pick(n)]; }
  else if (mode === 1) { a = 1 + pick(maxValue); b = 1 + pick(maxValue); }
  else if (mode === 2) { a = 1; b = 100000; }
  else { a = b = sorted[pick(n)]; }
  return [root, Math.min(a, b), Math.max(a, b)];
}
